// Verdict: only the exact token PASS from the verifier AND clean deterministic checks open the gate.
const v = String($input.first().json.text || '');
const lines = v.split(/\r?\n/).map((s) => s.replace(/^[*_`#>\s]+|[*_`#>\s]+$/g, '').trim()).filter(Boolean);
const last = (lines[lines.length - 1] || '').toUpperCase();
const token_pass = last === 'FINAL_STATUS: PASS';
const chk = $('Diff and Checks').first().json;
const final_pass = token_pass && chk.deterministic_ok === true;
let why = '';
if (!token_pass) why += 'Verifier last line was "' + (lines[lines.length - 1] || '(empty)') + '", not exactly FINAL_STATUS: PASS. ';
if (chk.deterministic_ok !== true) why += 'Deterministic checks did not pass (see report). ';
return [{ json: { final_pass, token_pass, deterministic_ok: chk.deterministic_ok === true, verifier_last_line: lines[lines.length - 1] || '', why: why.trim(), verifier_text: v, review_packet: 'VERIFIER OUTPUT:\n' + v + '\n\nDETERMINISTIC CHECKS (computed by code):\n' + chk.report_text } }];

