      warnings.push('PDF text came back joined; page numbers may be unreliable');
    } else pages = [];
  }
  pages.forEach((p, i) => {
    const t = String(p).replace(/[ \t]+\n/g, '\n').trim();
    units.push({ loc: 'Page ' + (i + 1), n: i + 1, text: t || '(no extractable text on this page)' });
  });
  loc_max = pages.length;
} else if (ext === 'csv') {
  kind = 'csv';
  const text = String($json.raw_text || '').replace(/^﻿/, '');
  const lines = text.split(/\r?\n/);
  let start = 0;
  const comments = [];
  while (start < lines.length && lines[start].trim().startsWith('#')) { comments.push(lines[start].trim()); start++; }
  const rows = parseCSV(lines.slice(start).join('\n'));
  const header = (rows.shift() || []).map((h) => h.trim());
  const data = rows.filter((r) => r.some((c) => String(c).trim() !== ''));
  const compact = data.length > 50; // long tables: column names once in the source header, values only per row
  if (compact) columns = header;
  data.forEach((r, i) => {
    const cell = (ci) => String(r[ci] === undefined ? '' : r[ci]).trim();
    const fields = compact ? header.map((h, ci) => cell(ci)).join(' | ') : header.map((h, ci) => h + ': ' + cell(ci)).join(' | ');
    units.push({ loc: 'Row ' + (i + 1), n: i + 1, id: String(r[0] === undefined ? '' : r[0]).trim(), text: fields });
  });
  loc_max = data.length;
  warnings.push('Row numbers count data rows after the header row');
  if (comments.length) warnings.push('Comment header ignored for row numbering: ' + comments.join(' / '));
} else {
  kind = 'txt';
  const text = String($json.raw_text || '').replace(/^﻿/, '');
  const lines = text.split(/\r?\n/);
  lines.forEach((l, i) => { if (l.trim() !== '') units.push({ loc: 'Line ' + (i + 1), n: i + 1, text: l.trim() }); });
  loc_max = lines.length;
  if (ext !== 'txt') warnings.push('Unrecognised extension "' + ext + '" read as plain text');
}
if (units.length === 0) warnings.push('No readable content found');
return { json: { source_id, filename, ext, kind, unit_count: units.length, loc_max, columns, units, warnings } };

