return { json: { ...item.json, raw_text: raw } };

// Build Source Record: turn one parsed file into citable units (Page n / Row n / Line n).
const meta = $json.filename !== undefined && $json.source_id !== undefined ? $json : $('Each File').item.json;
const ext = String(meta.ext || '').toLowerCase();
const filename = meta.filename;
const source_id = meta.source_id;
const warnings = [];
const units = [];
let kind = ext;
let loc_max = 0;
let columns = null;

function parseCSV(s) {
  const rows = [];
