const a=$input.first().json;if(a.integration_check!=='PASS')throw new Error('integration check failed');
const e2=a.planning;const lines=String(e2.text).split('\n');const i=lines.findIndex(l=>l.startsWith('WBS_SUMMARY'));
const safe=s=>String(s??'').replace(/\r?\n/g,' ');const refs=(a.memory.citations||[]).map(c=>c.tag||c.document_id||'').filter(Boolean).join(' ')||'NONE';
const mem=['MEMORY_CONTEXT (draft; source-grounded): '+safe(a.memory.ai_analysis?.answer||a.memory.answer),'MEMORY_CITATIONS: '+refs];
const out=i<0?[...lines,...mem]:[...lines.slice(0,i),...mem,...lines.slice(i)];
return [{json:{text:out.join('\n'),a_planning:e2.a_planning,a_memory:a.memory,a_integration_check:'PASS',source_pack_check:$('A Group - Inputs').first().json.source_pack_check,approval_status:'PENDING',approved_for_jira:false}}];

// ---- shared deterministic checks (no model involved) ----
function checkCitations(text, sources, units) {
  text = String(text).replace(/\\\|/g, '|');
  const re = /\[([^\[\]|]+?)\s*\|\s*(Page|Row|Line)\s*(\d+)(?:\s*[-–]\s*(\d+))?([^\[\]]*)\]/gi;
  const byKey = new Map();
  sources.forEach((s) => { byKey.set(String(s.source_id).toLowerCase(), s); byKey.set(String(s.filename).toLowerCase(), s); });
  let total = 0, valid = 0;
  const invalid = [];
  let m;
  while ((m = re.exec(String(text))) !== null) {
    total++;
    const label = m[1].trim();
    const word = m[2].toLowerCase();
    const a = parseInt(m[3], 10);
    const b = m[4] ? parseInt(m[4], 10) : a;
    const s = byKey.get(label.toLowerCase());
    let reason = null;
    if (!s) reason = 'unknown source "' + label + '"';
    else {
      const expect = s.kind === 'pdf' ? 'page' : s.kind === 'csv' ? 'row' : 'line';
      if (expect !== word) reason = 'source ' + s.filename + ' is ' + s.kind + ' so expects ' + expect + ', got ' + word;
      else if (a < 1 || b < a || b > s.loc_max) reason = 'location ' + a + (b !== a ? '-' + b : '') + ' is outside 1-' + s.loc_max;
      else if (s.kind === 'csv' && a === b && Array.isArray(units)) {
        const im = /id\s*=\s*([^\s\]|]+)/i.exec(m[5] || '');
        if (im) {
          const u = units.find((x) => x.filename === s.filename && x.loc === 'Row ' + a);
          if (u && u.id && u.id !== im[1]) reason = 'row ' + a + ' of ' + s.filename + ' has id=' + u.id + ', not id=' + im[1];
        }
      }
    }
    if (reason) invalid.push({ tag: m[0].slice(0, 120), reason }); else valid++;
  }
  const bare = (String(text).match(/\[(BRIEF|SPONSOR)\]/g) || []).length;
  const na = (String(text).match(/location n\/a/gi) || []).length;
  return { total, valid, invalid_count: invalid.length, invalid: invalid.slice(0, 25), unlocated: bare + na };
}

function parseRegister(text) {
  const rows = [];
  let header = null;
  for (const raw of String(text).split(/\r?\n/)) {
    if (!raw.includes('|')) continue;
    const line = raw.replace(/\[[^\]]*\]/g, (m) => m.replace(/\|/g, '¦'));
    if (/^[\s|:\-]+$/.test(line)) continue;
    const cells = line.split('|').map((c) => c.trim().replace(/\u00a6/g, '|'));
    if (cells.length && cells[0] === '') cells.shift();
    if (cells.length && cells[cells.length - 1] === '') cells.pop();
    if (cells.length < 10) continue;
    if (!header && /risk id/i.test(cells[0])) { header = cells.map((c) => c.toLowerCase()); continue; }
    if (header && /^R-[SO]-\d+/i.test(cells[0])) {
      const o = {};
      header.forEach((h, i) => { o[h] = cells[i] === undefined ? '' : cells[i]; });
      rows.push(o);
    }
  }
  return { header, rows };
}

function checkArithmetic(rows) {
  const mismatches = [];
  const flags = [];
  let scored = 0;
  for (const r of rows) {
    const id = r['risk id'];
    const L = parseInt(r['likelihood'], 10), I = parseInt(r['impact'], 10);
    const S = parseInt(r['risk score'], 10);
    const status = String(r['score status'] || '').toUpperCase();
    const numeric = !isNaN(L) && !isNaN(I);
    if (status === 'UNSCORED') {
      if (numeric || !isNaN(S)) flags.push(id + ': UNSCORED but numeric fields are not blank');
      continue;
    }
    if (!numeric) { flags.push(id + ': no numeric Likelihood/Impact and status is not UNSCORED'); continue; }
    if (L < 1 || L > 5 || I < 1 || I > 5) { mismatches.push({ id, stated: S, expected: 'L/I outside 1-5 (' + L + ',' + I + ')' }); continue; }
    scored++;
    if (S !== L * I) mismatches.push({ id, stated: isNaN(S) ? 'blank' : S, expected: L * I });
  }
  return { rows: rows.length, scored, mismatch_count: mismatches.length, mismatches: mismatches.slice(0, 25), flags: flags.slice(0, 25) };
}

function diffRegisters(orig, corr) {
  const oIds = orig.map((r) => r['risk id']);
  const cIds = corr.map((r) => r['risk id']);
  const missing = oIds.filter((x) => !cIds.includes(x));
  const added = cIds.filter((x) => !oIds.includes(x));
  const changed = [];
  for (const c of corr) {
    const o = orig.find((r) => r['risk id'] === c['risk id']);
    if (!o) continue;
    for (const k of Object.keys(c)) {
      if (String(o[k] === undefined ? '' : o[k]) !== String(c[k])) changed.push({ id: c['risk id'], column: k, old: String(o[k] === undefined ? '' : o[k]).slice(0, 160), new: String(c[k]).slice(0, 160) });
    }
  }
  return { missing, added, changed: changed.slice(0, 200), changed_count: changed.length };
}

// Citation Check - Register: deterministic check of every citation in the WBS and the scored register.
const pack = $('Build Evidence Pack').first().json;
const critic = String($input.first().json.text || '');
const wbs = String($('WBS Planner').first().json.text || '');
const register = String($('Risk Scorer').first().json.text || '');
const cite = checkCitations(wbs + '\n' + register, pack.source_index || [], pack.units || []);
const m = /CRITIC_STATUS\s*=\s*([A-Z_]+)/.exec(critic);
const critic_status = m ? m[1] : 'UNKNOWN';
const reg = parseRegister(register);
const arith = checkArithmetic(reg.rows);
const lines = [];
lines.push('CITATION_CHECK (WBS + register): total=' + cite.total + ' valid=' + cite.valid + ' invalid=' + cite.invalid_count + ' unlocated=' + cite.unlocated);
cite.invalid.forEach((x) => lines.push('  INVALID ' + x.tag + ' -> ' + x.reason));
lines.push('ARITHMETIC_CHECK (register): rows=' + arith.rows + ' scored=' + arith.scored + ' mismatches=' + arith.mismatch_count);
arith.mismatches.forEach((x) => lines.push('  MISMATCH ' + x.id + ': stated ' + x.stated + ', expected ' + x.expected));
arith.flags.forEach((x) => lines.push('  FLAG ' + x));
const report_text = lines.join('\n');
return [{
  json: {
    critic_text: critic,
    critic_status,
    citation: cite,
    arithmetic: arith,
    register_rows: reg.rows.length,
    report_text,
    review_packet: 'CRITIC OUTPUT:\n' + critic + '\n\nDETERMINISTIC CHECKS (computed by code, not by a model):\n' + report_text,
  },
}];

// Parse Human Decision: classify the reviewer's response. Fail-closed: anything unclear stops the run.
const j = $input.first().json;
const resp = String(j['Review Response'] !== undefined ? j['Review Response'] : (j.review_response || '')).trim();
const name = String(j['Reviewer Name'] !== undefined ? j['Reviewer Name'] : (j.reviewer_name || '')).trim();
const packet = $('Citation Check - Register').first().json;
const cs = packet.critic_status;
const runLabel = String($('Build Evidence Pack').first().json.run_label || '');
const up = resp.toUpperCase();
let route = 'STOP', status = '', reason = '';
if (!resp || !name) { status = 'STOPPED_INCOMPLETE_REVIEW'; reason = 'Missing review response or reviewer name'; }
else if (/^REJECT\b/.test(up)) { status = 'STOPPED_REJECTED'; }
else if (/^REQUEST CHANGES\b/.test(up)) { status = 'STOPPED_CHANGES_REQUESTED'; }
else if (/^APPROVE ALL RECOMMENDED\b/.test(up) || /^APPROVE SELECTED\s*:/.test(up) || /(^|\n)\s*OVERRIDE\s*:/.test(up)) { route = 'APPLY'; status = 'APPLYING_APPROVED_CHANGES'; }
else if (/^APPROVE\b/.test(up)) {
  if (cs === 'PASS') { route = 'APPLY'; status = 'APPROVED_NO_CHANGES'; }
  else { status = 'STOPPED_INVALID_APPROVAL'; reason = 'Plain APPROVE is allowed only when CRITIC_STATUS=PASS (it was ' + cs + ')'; }
} else { status = 'STOPPED_UNRECOGNISED_DECISION'; reason = 'Decision text was not recognised'; }
return [{
  json: {
    route,
    decision_status: status,
    reason,
    decision_text: resp,
    reviewer_name: name,
    critic_status: cs,
    decided_at: new Date().toISOString(),
    simulated: /SIMULATED/i.test(runLabel) || /SIMULATED/i.test(name),
  },
}];

// ---- shared deterministic checks (no model involved) ----
function checkCitations(text, sources, units) {
  text = String(text).replace(/\\\|/g, '|');
  const re = /\[([^\[\]|]+?)\s*\|\s*(Page|Row|Line)\s*(\d+)(?:\s*[-–]\s*(\d+))?([^\[\]]*)\]/gi;
  const byKey = new Map();
  sources.forEach((s) => { byKey.set(String(s.source_id).toLowerCase(), s); byKey.set(String(s.filename).toLowerCase(), s); });
  let total = 0, valid = 0;
  const invalid = [];
  let m;
  while ((m = re.exec(String(text))) !== null) {
    total++;
    const label = m[1].trim();
    const word = m[2].toLowerCase();
    const a = parseInt(m[3], 10);
    const b = m[4] ? parseInt(m[4], 10) : a;
    const s = byKey.get(label.toLowerCase());
    let reason = null;
    if (!s) reason = 'unknown source "' + label + '"';
    else {
      const expect = s.kind === 'pdf' ? 'page' : s.kind === 'csv' ? 'row' : 'line';
      if (expect !== word) reason = 'source ' + s.filename + ' is ' + s.kind + ' so expects ' + expect + ', got ' + word;
      else if (a < 1 || b < a || b > s.loc_max) reason = 'location ' + a + (b !== a ? '-' + b : '') + ' is outside 1-' + s.loc_max;
      else if (s.kind === 'csv' && a === b && Array.isArray(units)) {
        const im = /id\s*=\s*([^\s\]|]+)/i.exec(m[5] || '');
        if (im) {
          const u = units.find((x) => x.filename === s.filename && x.loc === 'Row ' + a);
          if (u && u.id && u.id !== im[1]) reason = 'row ' + a + ' of ' + s.filename + ' has id=' + u.id + ', not id=' + im[1];
        }
      }
    }
    if (reason) invalid.push({ tag: m[0].slice(0, 120), reason }); else valid++;
  }
  const bare = (String(text).match(/\[(BRIEF|SPONSOR)\]/g) || []).length;
  const na = (String(text).match(/location n\/a/gi) || []).length;
  return { total, valid, invalid_count: invalid.length, invalid: invalid.slice(0, 25), unlocated: bare + na };
}

function parseRegister(text) {
  const rows = [];
  let header = null;
  for (const raw of String(text).split(/\r?\n/)) {
    if (!raw.includes('|')) continue;
    const line = raw.replace(/\[[^\]]*\]/g, (m) => m.replace(/\|/g, '¦'));
    if (/^[\s|:\-]+$/.test(line)) continue;
    const cells = line.split('|').map((c) => c.trim().replace(/\u00a6/g, '|'));
    if (cells.length && cells[0] === '') cells.shift();
    if (cells.length && cells[cells.length - 1] === '') cells.pop();
    if (cells.length < 10) continue;
    if (!header && /risk id/i.test(cells[0])) { header = cells.map((c) => c.toLowerCase()); continue; }
    if (header && /^R-[SO]-\d+/i.test(cells[0])) {
      const o = {};
      header.forEach((h, i) => { o[h] = cells[i] === undefined ? '' : cells[i]; });
      rows.push(o);
    }
  }
  return { header, rows };
}

function checkArithmetic(rows) {
  const mismatches = [];
  const flags = [];
  let scored = 0;
  for (const r of rows) {
    const id = r['risk id'];
    const L = parseInt(r['likelihood'], 10), I = parseInt(r['impact'], 10);
    const S = parseInt(r['risk score'], 10);
    const status = String(r['score status'] || '').toUpperCase();
    const numeric = !isNaN(L) && !isNaN(I);
    if (status === 'UNSCORED') {
      if (numeric || !isNaN(S)) flags.push(id + ': UNSCORED but numeric fields are not blank');
      continue;
    }
    if (!numeric) { flags.push(id + ': no numeric Likelihood/Impact and status is not UNSCORED'); continue; }
    if (L < 1 || L > 5 || I < 1 || I > 5) { mismatches.push({ id, stated: S, expected: 'L/I outside 1-5 (' + L + ',' + I + ')' }); continue; }
    scored++;
    if (S !== L * I) mismatches.push({ id, stated: isNaN(S) ? 'blank' : S, expected: L * I });
  }
  return { rows: rows.length, scored, mismatch_count: mismatches.length, mismatches: mismatches.slice(0, 25), flags: flags.slice(0, 25) };
}

function diffRegisters(orig, corr) {
  const oIds = orig.map((r) => r['risk id']);
  const cIds = corr.map((r) => r['risk id']);
  const missing = oIds.filter((x) => !cIds.includes(x));
  const added = cIds.filter((x) => !oIds.includes(x));
  const changed = [];
  for (const c of corr) {
    const o = orig.find((r) => r['risk id'] === c['risk id']);
    if (!o) continue;
    for (const k of Object.keys(c)) {
      if (String(o[k] === undefined ? '' : o[k]) !== String(c[k])) changed.push({ id: c['risk id'], column: k, old: String(o[k] === undefined ? '' : o[k]).slice(0, 160), new: String(c[k]).slice(0, 160) });
    }
  }
  return { missing, added, changed: changed.slice(0, 200), changed_count: changed.length };
}

// Diff and Checks: compare the original register with the corrected one and re-run deterministic checks.
const pack = $('Build Evidence Pack').first().json;
const original = String($('Risk Scorer').first().json.text || '');
const corrected = String($input.first().json.text || '');
const o = parseRegister(original);
const c = parseRegister(corrected);
const cite = checkCitations(corrected, pack.source_index || [], pack.units || []);
const arith = checkArithmetic(c.rows);
const diff = diffRegisters(o.rows, c.rows);
const empty = c.rows.length === 0;
const deterministic_ok = !empty && cite.invalid_count === 0 && arith.mismatch_count === 0 && diff.missing.length === 0 && diff.added.length === 0;
const lines = [];
lines.push('ROWS: original=' + o.rows.length + ' corrected=' + c.rows.length + (empty ? '  (CORRECTED REGISTER COULD NOT BE PARSED)' : ''));
lines.push('IDS_MISSING_FROM_CORRECTED: ' + (diff.missing.join(', ') || 'none'));
lines.push('IDS_ADDED_IN_CORRECTED: ' + (diff.added.join(', ') || 'none'));
lines.push('CITATION_CHECK (corrected register): total=' + cite.total + ' valid=' + cite.valid + ' invalid=' + cite.invalid_count + ' unlocated=' + cite.unlocated);
cite.invalid.forEach((x) => lines.push('  INVALID ' + x.tag + ' -> ' + x.reason));
lines.push('ARITHMETIC_CHECK (corrected register): rows=' + arith.rows + ' scored=' + arith.scored + ' mismatches=' + arith.mismatch_count);
arith.mismatches.forEach((x) => lines.push('  MISMATCH ' + x.id + ': stated ' + x.stated + ', expected ' + x.expected));
arith.flags.forEach((x) => lines.push('  FLAG ' + x));
lines.push('CELLS_CHANGED_VS_ORIGINAL: ' + diff.changed_count);
diff.changed.slice(0, 60).forEach((x) => lines.push('  ' + x.id + ' | ' + x.column + ' | OLD: ' + x.old + ' | NEW: ' + x.new));
lines.push('DETERMINISTIC_OK=' + deterministic_ok);
return [{
  json: {
    corrected_text: corrected,
    citation: cite,
    arithmetic: arith,
    diff,
    deterministic_ok,
    report_text: lines.join('\n'),
  },
}];

