// Verdict: only the exact token PASS from the verifier AND clean deterministic checks open the gate.
const v = String($input.first().json.text || '');
const lines = v.split(/\r?\n/).map((s) => s.replace(/^[*_`#>\s]+|[*_`#>\s]+$/g, '').trim()).filter(Boolean);
const last = (lines[lines.length - 1] || '').toUpperCase();
const token_pass = last === 'FINAL_STATUS: PASS';
const chk = $('Diff and Checks').first().json;
const final_pass = token_pass && chk.deterministic_ok === true;
let why = '';
if (!token_pass) why += 'Verifier last line was "' + (lines[lines.length - 1] || '(empty)') + '", not exactly FINAL_STATUS: PASS. ';
if (chk.deterministic_ok !== true) why += 'Deterministic checks did not pass (see report). ';
return [{ json: { final_pass, token_pass, deterministic_ok: chk.deterministic_ok === true, verifier_last_line: lines[lines.length - 1] || '', why: why.trim(), verifier_text: v, review_packet: 'VERIFIER OUTPUT:\n' + v + '\n\nDETERMINISTIC CHECKS (computed by code):\n' + chk.report_text } }];

// Final Result: one audit-ready record of the run. Nothing here writes to any external system.
const get = (name) => { try { return $(name).first().json; } catch (e) { return null; } };
const here = $input.first().json;
const pack = get('Build Evidence Pack');
const crit = get('Citation Check - Register');
const dec = get('Parse Human Decision');
const chk = get('Diff and Checks');
const ver = get('Verdict');
const esc = get('Escalation Review');
const status = here.final_status;
const simulated = !!(dec && dec.simulated);
const approved_for_jira = status === 'VERIFIED_PASS' && !simulated;
return [{
  json: {
    final_status: status,
    approved_for_jira,
    simulated_test_only: simulated,
    run_label: pack ? pack.run_label : '',
    finished_at: new Date().toISOString(),
    sources: pack ? pack.source_index : [],
    pack_stats: pack ? { files: pack.file_count, units: pack.unit_count, chars: pack.pack_chars, est_tokens: pack.est_tokens, warnings: pack.warnings } : null,
    wbs: (get('WBS Planner') || {}).text || '',
    a_planning: (get('WBS Planner') || {}).a_planning || null,
    a_memory: (get('WBS Planner') || {}).a_memory || null,
    a_integration_check: (get('WBS Planner') || {}).a_integration_check || 'NOT_RUN',
    register_scored: (get('Risk Scorer') || {}).text || '',
