    register_corrected: chk ? chk.corrected_text : '',
    checks_after_correction: chk ? chk.report_text : '',
    verifier: ver ? { final_pass: ver.final_pass, token_pass: ver.token_pass, deterministic_ok: ver.deterministic_ok, last_line: ver.verifier_last_line, why: ver.why, text: ver.verifier_text } : null,
