const site = 'https://xiaojingli002.atlassian.net';
const apiBase = 'https://api.atlassian.com/ex/jira/089ef7b2-a8d2-4128-99f4-b3e292391b3b';
const project = 'HCH';
const taskTypeId = '10048';
const approver = $('Validate reviewer inputs').first().json.reviewer;
const writeEnabled = true;
const draft = $('Read pending draft').first().json;
if (!draft.id) throw new Error('Draft missing, already decided, or stale.');
if ($input.first().json.state === 'CHANGE_OPEN') throw new Error('Week 12 change hold. Reconcile the baseline before Jira approval.');
const writeRequested = writeEnabled;
const input = JSON.parse(draft.payload);
if (input.source_version !== draft.source_version) throw new Error('Draft source version mismatch.');
if (!Array.isArray(input.items) || input.items.length < 1 || input.items.length > 60) {
  throw new Error('Provide an items array with 1–60 entries.');
}
const required = (value, name, max) => {
  if (typeof value !== 'string' || !value.trim() || value.trim().length > max) throw new Error('Invalid ' + name);
  return value.trim();
};
const seen = new Set();
const items = input.items.map(item => {
  const externalId = required(item.external_id, 'external_id', 48).toUpperCase();
  if (!/^[A-Z0-9]+(?:[._-][A-Z0-9]+)*$/.test(externalId) || seen.has(externalId)) {
    throw new Error('Invalid or repeated external_id: ' + externalId);
  }
  seen.add(externalId);
  const kind = item.kind;
  if (!['wbs', 'milestone'].includes(kind)) throw new Error('Invalid kind for ' + externalId);
  const title = required(item.title, 'title', 170);
  const source = required(item.source, 'source', 4000);
  const details = item.details == null || item.details === '' ? '' : required(item.details, 'details', 3500);
  const timing = item.timing == null || item.timing === '' ? '' : required(item.timing, 'timing', 500);
  const dependencies = item.dependencies ?? [];
  if (!Array.isArray(dependencies) || dependencies.length > 20) throw new Error('Invalid dependencies');
  const refs = dependencies.map(dep => required(dep, 'dependency', 48));
  const label = 'hch-' + externalId.toLowerCase();
  const summary = '[' + externalId + '] ' + (kind === 'milestone' ? '[Milestone] ' : '') + title;
  const lines = ['External ID: ' + externalId, 'Kind: ' + kind, 'Source: ' + source];
  if (timing) lines.push('Timing: ' + timing);
  if (refs.length) lines.push('Dependencies: ' + refs.join(', '));
  if (details) lines.push(...details.split(/\r?\n/).filter(line => line.trim()));
  return {externalId, kind, label, summary, lines, description:{type:'doc', version:1,
    content:lines.map(text => ({type:'paragraph', content:[{type:'text',text}]}))}};
});
const jql = 'project = "' + project + '" AND labels in (' + items.map(item => '"' + item.label + '"').join(', ') + ')';
const fields = ['project','summary','description','labels','updated','issuetype','status'];
return [{json:{site,apiBase,project,taskTypeId,approver,writeRequested,items,query:{jql,maxResults:100,fields}}}];

const config = $('Sandbox settings and validation').first().json;
const project = $('Read sandbox project').first().json;
if (project.key !== config.project) throw new Error('Sandbox project key mismatch');
if (config.writeRequested && !project.issueTypes?.some(type => type.id === config.taskTypeId && !type.subtask)) {
  throw new Error('Task issue type is unavailable for the sandbox project');
}
const response = $input.first().json;
const sameDescription = (actual, wanted) => {
  if (actual?.type !== 'doc' || actual.version !== 1 || actual.content?.length !== wanted.content.length) return false;
  return wanted.content.every((paragraph, index) => {
    const candidate = actual.content[index];
    const text = candidate?.content?.[0];
    return candidate?.type === 'paragraph' && candidate.content?.length === 1 && text?.type === 'text' &&
      !text.marks?.length && text.text === paragraph.content[0].text;
  });
};
if (!Array.isArray(response.issues) || response.nextPageToken || response.isLast === false) {
  throw new Error('Jira search did not return a complete result. Stop before writing.');
}
const rows = config.items.map(item => {
  const matches = response.issues.filter(issue => issue.fields?.labels?.includes(item.label));
  if (matches.length > 1) throw new Error('Multiple Jira items have ' + item.label);
  const issue = matches[0];
  const before = issue ? {key:issue.key, summary:issue.fields.summary, description:issue.fields.description,
    labels:issue.fields.labels, updated:issue.fields.updated} : null;
  if (issue && (issue.fields.project?.key !== config.project || !before.labels.includes('ai-generated') ||
    (config.writeRequested && issue.fields.issuetype?.id !== config.taskTypeId))) {
    throw new Error('Matching Jira item is outside the managed set: ' + issue.key);
  }
  const unchanged = before && before.summary === item.summary &&
    sameDescription(before.description, item.description);
  const action = !before ? 'CREATE' : unchanged ? 'UNCHANGED' : 'UPDATE';
  return {...item, action, before};
});
const esc = text => String(text).replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const draft = $('Read pending draft').first().json;
const preview = '<p>Draft ' + esc(draft.id) + ' | Source version: ' + esc(draft.source_version) + '</p><p>Jira sandbox: ' + esc(project.name) + ' (' + esc(project.key) + ')</p>' +
  rows.map(row => '<p><strong>' + esc(row.action + ' ' + (row.before?.key ?? '') + ' ' + row.summary) +
    '</strong><br>' + (row.action === 'UPDATE' ? 'Before: ' + esc(row.before.summary) + '<br>' +
    esc(JSON.stringify(row.before.description)) + '<br>After:<br>' : '') + row.lines.map(esc).join('<br>') + '</p>').join('');
return [{json:{project:project.key, taskTypes:(project.issueTypes ?? []).map(({id,name,subtask})=>({id,name,subtask})),
  writeRequested:config.writeRequested, rows, preview}}];

const config = $('Sandbox settings and validation').first().json;
const response = $input.first().json;
const sameDescription = (actual, wanted) => {
  if (actual?.type !== 'doc' || actual.version !== 1 || actual.content?.length !== wanted.content.length) return false;
  return wanted.content.every((paragraph, index) => {
    const candidate = actual.content[index];
    const text = candidate?.content?.[0];
    return candidate?.type === 'paragraph' && candidate.content?.length === 1 && text?.type === 'text' &&
      !text.marks?.length && text.text === paragraph.content[0].text;
