  const unchanged = before && before.summary === item.summary &&
    sameDescription(before.description, item.description);
  const action = !before ? 'CREATE' : unchanged ? 'UNCHANGED' : 'UPDATE';
  return {...item, action, before};
});
const reviewed = $('Build review preview').first().json.rows;
const approval = $('Record decision').first().json;
if (!config.writeRequested || approval.decision !== 'APPROVED') throw new Error('Jira write blocked');
const actions = rows.map((row, index) => {
  if (row.action !== reviewed[index].action || row.before?.key !== reviewed[index].before?.key ||
    row.before?.updated !== reviewed[index].before?.updated) throw new Error('Proposal is stale for ' + row.externalId + '. Run again and review.');
  const creating = row.action === 'CREATE';
  const fields = {summary:row.summary, description:row.description};
  if (creating) Object.assign(fields,{project:{key:config.project}, issuetype:{id:config.taskTypeId}, labels:['ai-generated',row.label]});
  return {json:{...row, approval, fields, method:creating ? 'POST' : row.action === 'UPDATE' ? 'PUT' : 'GET',
    path:creating ? '/issue' : '/issue/' + encodeURIComponent(row.before.key)}};
});
return [{json:{actions}}];

const row = $('Process one Jira issue at a time').item.json;
if (!['CREATE', 'UPDATE', 'UNCHANGED'].includes(row.action)) throw new Error('Jira action is missing from the current loop item');
const response = $json;
const rawStatus = response.statusCode ?? response.code ?? response.error?.statusCode;
const status = Number(rawStatus) || null;
const issueKey = row.action === 'CREATE' ? (response.body?.key ?? response.key ?? null) : (row.before?.key ?? null);
const expectedStatus = {CREATE:201, UPDATE:204, UNCHANGED:200}[row.action];
const ok = status === expectedStatus && typeof issueKey === 'string';
const error = response.body?.errorMessages ?? response.body?.message ?? response.message ?? response.error?.message;
return {json:{...row,issueKey,write_http_status:status,action_ok:ok,
  action_error:ok ? null : (error ?? 'Unexpected Jira response'), action_at:new Date().toISOString()}};

const sameDescription = (actual, wanted) => {
  if (actual?.type !== 'doc' || actual.version !== 1 || actual.content?.length !== wanted.content.length) return false;
  return wanted.content.every((paragraph, index) => {
    const candidate = actual.content[index];
    const text = candidate?.content?.[0];
    return candidate?.type === 'paragraph' && candidate.content?.length === 1 && text?.type === 'text' &&
      !text.marks?.length && text.text === paragraph.content[0].text;
  });
};
const row = $('Record action results').item.json;
const config = $('Sandbox settings and validation').first().json;
const actual = $json.body;
const fields = actual?.fields;
const verified = $json.statusCode === 200 && actual.key === row.issueKey && fields?.project?.key === config.project &&
  fields.summary === row.summary && fields.labels?.includes('ai-generated') && fields.labels.includes(row.label) &&
  sameDescription(fields.description, row.description);
return {json:{...row.approval, external_id:row.externalId, action:row.action, issue_key:row.issueKey,
