const rows = $input.all().map(item => item.json);
const failures = rows.filter(row => row.result !== 'VERIFIED').length;
return [{json:{status:failures ? 'CHECK_REQUIRED' : 'VERIFIED', failures, rows}}];

const claim = $input.first().json;
const decision = $('Record decision').first().json;
if (claim.id !== decision.draft_id || claim.state !== 'PROCESSING') throw new Error('Another decision already closed this draft.');
return $('Check for stale approval').first().json.actions;

const input=$input.first().json;
const id=Number(input.draft_id);
const decision=String(input.decision??'').trim().toUpperCase();
const preview=String(input.preview_execution??'').trim();
if (!Number.isSafeInteger(id) || id<1 || !['PREVIEW','REJECT','APPROVE'].includes(decision)) throw new Error('Enter a draft ID and PREVIEW, REJECT or APPROVE.');
if (decision!=='PREVIEW' && !/^\d+$/.test(preview)) throw new Error('Enter the exact preview execution ID before recording a decision.');
return [{json:{id,decision,preview,reviewer:'YAO ZHI',reviewer_account:'xiaojing002@e.ntu.edu.sg',identity_method:'private n8n editor'}}];

const controls=$('Validate reviewer inputs').first().json;
const draft=$('Read pending draft').first().json;
const plan=$input.first().json;
const snapshot=JSON.stringify(plan.rows.map(r=>[r.externalId,r.action,r.summary,r.lines,r.before?.key??null,r.before?.updated??null]));
const execution_id=String($execution.id);
const audit={draft_id:draft.id,execution_id,source_version:draft.source_version,project:plan.project,
  decision:controls.decision==='APPROVE'?'APPROVED':controls.decision==='REJECT'?'REJECTED':'PREVIEW',
