  identity_method:controls.identity_method,preview_execution:controls.decision==='PREVIEW'?execution_id:controls.preview};
if (controls.decision!=='PREVIEW') {
  const previous=JSON.parse(draft.audit??'null');
  if (!previous || previous.preview_execution!==controls.preview || previous.snapshot!==snapshot || previous.source_version!==draft.source_version) {
    throw new Error('The draft or Jira state changed, or the preview execution ID is wrong. Run PREVIEW again.');
  }
}
return [{json:{...audit,snapshot}}];

const row=$input.first().json;
const preview=$('Build review preview').first().json;
const decision=$('Record decision').first().json;
if (row.id!==decision.draft_id) throw new Error('Could not save the preview.');
return [{json:{draft_id:row.id,preview_execution:decision.execution_id,project:preview.project,
  status:'READY_FOR_HUMAN_REVIEW',rows:preview.rows.map(r=>({action:r.action,external_id:r.externalId,
    jira_key:r.before?.key??null,before:r.before?.summary??null,summary:r.summary,description:r.lines})),
  next:'Check these exact actions. Set Reviewer controls to REJECT or APPROVE with this draft_id and preview_execution, then run again.'}}];

const row=$input.first().json;
if(row.state!=='REJECTED') throw new Error('Rejection could not be saved.');
return [{json:{draft_id:row.id,state:row.state,jira_writes:0,audit:JSON.parse(row.audit)}}];

const row=$input.first().json;
if(!row.id || !['VERIFIED','CHECK_REQUIRED'].includes(row.state)) throw new Error('Could not persist the batch audit.');
return [{json:{draft_id:row.id,state:row.state,...JSON.parse(row.audit)}}];

const auth=$input.first().json;
const email=auth.user?.email?.trim().toLowerCase();
if(!auth.user?.id||!email) throw new Error('Sign in to n8n to submit a change.');
const mode=auth.Mode;
if(!['Simulation','Formal sponsor change'].includes(mode)) throw new Error('Choose a valid change mode.');
const reference=String(auth['Event reference']||'').trim();
const memo=String(auth['Memo text (verbatim)']||'').trim();
if(!reference||reference.length>150||!memo||memo.length>6000) throw new Error('Invalid event reference or memo text');
return [{json:{mode,reference,memo,detected_at:auth.submittedAt,received_by:email,execution_id:String($execution.id)}}];

const note=String($json.text||'');
const ev=$('Build change data pack').first().json;
const pk=ev.pack_text;
const norm=s=>s.replace(/\s*\|\s*/g,'|').replace(/\s+/g,' ');
const valid=new Set((pk.match(/^\[[^\]]+\]/gm)||[]).map(norm));
const cites=(note.match(/\[[0-9]{2}_[^\]|]+\|\s*(?:Row|Line)\s*\d+\s*\]/g)||[]).map(norm);
const invalid=[...new Set(cites.filter(c=>!valid.has(c)))];
const codes=[...new Set(note.match(/\b[DR][0-9]{2}\b/g)||[])];
const invented=codes.filter(c=>!new RegExp('^\\[[^\\]]+\\] '+c+',','m').test(pk));
