if (!/^MILESTONES[^\n]*$/m.test(corrected) || !/^DEPENDENCIES[^\n]*$/m.test(corrected)) {
  throw new Error('Corrected WBS lost a required output section.');
}
return [{json:{
  text:corrected,
  a_planning:base.a_planning,
  a_memory:base.a_memory,
  a_integration_check:base.a_integration_check,
  source_pack_check:base.source_pack_check,
  approval_status:'PENDING',
