  wbs_review:{critic:$('WBS Constraint Critic').first().json.text,reviewer:$('WBS Human Review').first().json['Reviewer Name'],decision:$('WBS Human Review').first().json['Review Response'],simulated:false,verifier:verdict}
}}];
